[metadata] {"type": "create", "filePath": "/workspace/repo/packages/bruno-app/src/components/ApiSpecPanel/Renderers/Swagger/serializeBody.js", "content": "/**
 * Serializes a request body produced by the Swagger "try it out" panel into a
 * value that Bruno's request layer can send.
 *
 * Swagger UI hands us a variety of body shapes depending on the operation's
 * content type. We support the ones Bruno can currently forward as-is (strings,
 * URL-encoded forms) and throw a descriptive error for the ones that would
 * require a full multipart / binary request pipeline.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Human-readable message describing why a given body type can't be sent from
 * the spec panel, along with the alternatives that do work.
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported body types are JSON, URL-encoded forms, plain text, and URLSearchParams.`;

const unsupportedBodyError = (bodyType, hint) => {
  const error = new TypeError(`${hint} ${UNSUPPORTED_BODY_MESSAGE(bodyType)}`);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    return body.toString();
  }

  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    throw unsupportedBodyError(
      'FormData',
      'Multipart form data from the spec panel is not supported. Create a Bruno request to send multipart form data.'
    );
  }

  // File extends Blob, so it must be checked first.
  if (typeof File !== 'undefined' && body instanceof File) {
    throw unsupportedBodyError('File', 'File upload from the spec panel is not supported.');
  }

  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    throw unsupportedBodyError('Blob', 'Binary file upload from the spec panel is not supported.');
  }

  if (typeof ArrayBuffer !== 'undefined' && body instanceof ArrayBuffer) {
    throw unsupportedBodyError('ArrayBuffer', 'Binary data from the spec panel is not supported.');
  }

  if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(body)) {
    const bodyType = body?.constructor?.name || 'TypedArray';
    throw unsupportedBodyError(bodyType, 'Binary data from the spec panel is not supported.');
  }

  const bodyType = body?.constructor?.name || typeof body;
  throw unsupportedBodyError(bodyType, `${bodyType} from the spec panel is not supported.`);
};

export default serializeBody;
