const axios = require('axios');

/**
 * Proxies an HTTP request for the Swagger "try it out" panel through the
 * Electron main process. Running the request here (instead of in the renderer)
 * avoids browser CORS restrictions and lets us reuse Node's networking stack.
 *
 * @param {Object} [payload]
 * @param {string} payload.url       Fully-qualified request URL.
 * @param {string} [payload.method]  HTTP method.
 * @param {Object} [payload.headers] Request headers.
 * @param {string} [payload.body]    Serialized request body.
 * @returns {Promise<Object>} A success, error, or validation-failure object.
 */
const proxySwaggerFetch = async (payload) => {
  if (!payload || !payload.url) {
    return { error: true, code: 'INVALID_REQUEST' };
  }

  const { url, method, headers, body } = payload;

  try {
    const response = await axios({
      url,
      method,
      headers,
      data: body,
      responseType: 'arraybuffer',
      // Accept every status code (including 5xx / custom codes like 599) so the
      // panel can render non-2xx responses instead of treating them as errors.
      validateStatus: () => true
    });

    // AxiosHeaders (axios v1) exposes a toJSON() that yields a plain object.
    let responseHeaders = response.headers;
    if (responseHeaders && typeof responseHeaders.toJSON === 'function') {
      responseHeaders = responseHeaders.toJSON();
    }

    return {
      status: response.status,
      statusText: response.statusText,
      headers: responseHeaders,
      bodyBase64: Buffer.from(response.data).toString('base64')
    };
  } catch (error) {
    return { error: true, code: error.code, message: error.message };
  }
};

const registerSwaggerFetchIpc = () => {
  ipcMain.handle('renderer:swagger-fetch', (event, payload) => proxySwaggerFetch(payload));
};

module.exports = registerSwaggerFetchIpc;
module.exports.proxySwaggerFetch = proxySwaggerFetch;
